SEP = "|"
QUOTE = "'"


def _scan(text):
    """Split text on SEP outside quotes.

    Each field comes back as a list of (char, quoted) pairs. The quote characters
    that delimit a quoted section are dropped; two QUOTE characters in a row inside
    a quoted section become one literal QUOTE.
    """
    fields, field = [], []
    quoted = False
    i = 0
    while i < len(text):
        ch = text[i]
        if ch == QUOTE:
            if quoted and text[i + 1:i + 2] == QUOTE:
                field.append((QUOTE, True))
                i += 2
                continue
            quoted = not quoted
        elif ch == SEP and not quoted:
            fields.append(field)
            field = []
        else:
            field.append((ch, quoted))
        i += 1
    if quoted:
        raise ValueError(f"unclosed quote in {text!r}")
    fields.append(field)
    return fields


def _trim(chars):
    """Join the pairs from _scan, dropping whitespace that is not inside quotes at the ends."""
    lo, hi = 0, len(chars)
    while lo < hi and not chars[lo][1] and chars[lo][0].isspace():
        lo += 1
    while hi > lo and not chars[hi - 1][1] and chars[hi - 1][0].isspace():
        hi -= 1
    return "".join(ch for ch, _ in chars[lo:hi])


def parse_fields(text):
    """Parse a line like name=Ann| note='hi| there' into a dict of strings.

    Fields are separated by SEP. Whitespace around keys and around unquoted values is
    ignored. A value may be wrapped in QUOTE characters; inside quotes, SEP and '='
    are ordinary characters, whitespace is kept, and two QUOTE characters in a row
    stand for one QUOTE character. Empty fields, such as one after a trailing SEP,
    are skipped, so a blank line gives {}. A field without '=', an empty key, a
    quote that is never closed, or a key that appears twice raises ValueError.
    """
    result = {}
    for field in _scan(text):
        if all(not quoted and ch.isspace() for ch, quoted in field):
            continue
        eq = next(
            (i for i, (ch, quoted) in enumerate(field) if ch == "=" and not quoted), None
        )
        if eq is None:
            raise ValueError(f"field without '=': {_trim(field)!r}")
        key = _trim(field[:eq])
        if not key:
            raise ValueError(f"empty key in {_trim(field)!r}")
        if key in result:
            raise ValueError(f"duplicate key: {key!r}")
        result[key] = _trim(field[eq + 1:])
    return result

